    "_Followed by {named} and %n other you follow_::_Followed by {named} and %n others you follow_" : ["Seko {named} un %n citi, kam sekojat", "Seko {named} un %n citas personas, kurām sekojat", "Seko {named} un %n citas personas, kurām sekojat"],
